import type { Focus, Mission } from "../lib/types";
import { spiritualLife } from "./spiritual-life";

/** Original editorial applications, not a Bible translation. All await human review.
 * Passage sources, interpretive cautions and review ledger: docs/virtude/CONTENT-REVIEW.md.
 */
export const focusLabels: Record<Focus, string> = {
  self_control: "Paciência e domínio próprio",
  relationships: "Relacionamentos e perdão",
  stewardship: "Sabedoria financeira e profissional",
  spiritual_life: "Vida espiritual",
};

type Draft = [
  day: number, title: string, reference: string, context: string,
  principle: string, practice: string, simplified: string,
  deepened: string, reflectionQuestion: string,
];

// Published identifiers must survive text revisions and array reordering.
const prefixes: Record<Focus, string> = {
  self_control: "10000001", relationships: "10000002", stewardship: "10000003", spiritual_life: "10000004",
};

function build(focus: Focus, drafts: Draft[]): Mission[] {
  return drafts.map(([day, title, reference, context, principle, practice, simplified, deepened, reflectionQuestion]) => ({
    id: `${prefixes[focus]}-0000-4000-8000-${String(day).padStart(12, "0")}`,
    focus, day,
    phase: day <= 3 ? "autoconhecimento" : day <= 7 ? "aprendizado" : day <= 14 ? "aplicação" : day <= 18 ? "consolidação" : "reflexão",
    title, reference, context, principle, practice, simplified, deepened, reflectionQuestion,
    reviewStatus: "pending_review",
  }));
}

