export const missions: Mission[] = [
  ...build("self_control", selfControl),
  ...build("relationships", relationships),
  ...build("stewardship", stewardship),
  ...build("spiritual_life", spiritualLife),
];

export function getMission(focus: Focus, day: number): Mission | undefined {
  if (!Number.isInteger(day) || day < 1 || day > 21) return undefined;
  return missions.find((mission) => mission.focus === focus && mission.day === day);
}
